window.__saqPaperQuestions("2025-2-network-2",[{"number":1,"title":"","stemText":"You are the on-call Emergency Physician for a small regional Hospital. The overnight resident calls you worried about a case of respiratory distress being managed in the\nresuscitation bay. A 31-year-old male, known asthmatic, had presented 1 hour earlier with\nsaturations of 78%. He described a 3-hour history of worsening shortness of breath and chest pain despite frequent salbutamol use at home. This was on a background of 4 days of cough, fevers and wheeze The doctor had provided the following treatment to the patient 15L oxygen via mask  Continuous salbutamol via nebuliser  3x Ipratropium 500mcg nebules q20 minutely  100mg IV hydrocortisone  2x infusions of Magnesium sulfate 10mmol given over 20 minutes each \nCurrent Observations:\nSaturations 92% on oxygen via face mask\n\n\nRR 36\n\n\nHR 140\n\n\nBP 91/40\n\n\nTemp 37.8\n\n\nGCS 13: E3, V4, M6\n\n\nBSL 8.3\n  Bedside ultrasound - no evidence of pneumothorax","parts":[{"id":"a","label":"Part A","prompt":"List 5 examination features of Severe/Life Threatening Asthma (5 marks)"},{"id":"b","label":"Part B","prompt":"His condition has not improved since arrival despite seemingly appropriate asthma treatment. OTHER THAN severe/life-threatening asthma, list 5 differential diagnoses. (5 marks)"},{"id":"c","label":"Part C","prompt":"You are 30 minutes away from the Hospital. List 4 additional treatments you will\nrecommend being commenced before your arrival and a significant potential complication for each (4 marks)"},{"id":"d","label":"Part D","prompt":"You arrive to the resus room and decide to repeat the bedside Ultrasound.\nList 4 POCUS findings that exclude pneumothorax (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Inability to speak / single words</td></tr><tr><td></td><td>Increased work of breathing</td></tr><tr><td colspan=\"2\">Use of accessory muscles</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td colspan=\"2\">Intercostal recession</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td colspan=\"2\">Tracheal tug</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td></td><td>Silent chest</td></tr><tr><td></td><td>Cyanosis</td></tr><tr><td></td><td>Paradoxical respiration</td></tr><tr><td></td><td>Bradycardia</td></tr><tr><td></td><td>Agitation or delirium or reduced level of consciousness</td></tr><tr><td colspan=\"2\">(1 mark each but must have bold to get full marks)</td></tr><tr><td colspan=\"2\">Half mark</td></tr><tr><td></td><td>Pulsus paradoxus - impractical answer</td></tr><tr><td colspan=\"2\">Tachycardia, Heart rate in excess of 120 – too non specific, especially post ventolin</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Pulmonary Embolism</td></tr><tr><td></td><td>Pneumothorax</td></tr><tr><td></td><td>Pneumonitis</td></tr><tr><td></td><td>Heart failure / myocarditis</td></tr><tr><td></td><td>Acute Pulmonary Oedema</td></tr><tr><td colspan=\"2\"></td></tr><tr><td colspan=\"2\">Less ideal answers (0.5 mark each)</td></tr><tr><td></td><td>Upper airway obstruction – eg tracheitis, foreign body</td></tr><tr><td></td><td>Severe metabolic disturbance – DKA very unlikely with the normal BSL</td></tr><tr><td></td><td>Exacerbation of COPD (31 year old less likely)</td></tr><tr><td></td><td>Hyperventilation</td></tr><tr><td></td><td>Panic attack</td></tr><tr><td></td><td>Paradoxical cord movement</td></tr><tr><td></td><td>Anything obscure or rare like Q-Fever</td></tr><tr><td colspan=\"2\"><strong>c. You are 30 minutes away from the Hospital.   List 4 additional treatments you will </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td></td><td>Must not use the same complication for multiple treatments</td></tr><tr><td></td><td>Complication needs to be specific – ie “toxicity” or “reaction” is inadequate</td></tr><tr><td>Full Mark</td><td></td></tr><tr><td>Treatment</td><td>Potential Complication</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>IM/IV Adrenaline</td><td>Arrhythmia / Tachycardia / lactic acidosis</td><td></td></tr><tr><td>ii.  NIV</td><td>Aspiration / Pneumothorax / Hypotension</td><td></td></tr><tr><td>iii  Fluid Bolus</td><td>May exacerbate if heart failure</td><td></td></tr><tr><td>iv Salbutamol Infusion</td><td>Arrhythmia / Tachycardia / lactic acid / Hypokaleamia</td><td></td></tr><tr><td>v</td><td>Aminophylline infusion</td><td>Arrhythmia, Seizures, Hypokalaemia, N&amp;V, Aspiration</td></tr><tr><td colspan=\"3\">HALF MARK</td></tr><tr><td></td><td>Further MgSo4: Respiratory depression <em>(question is for additional treatments so </em></td><td></td></tr><tr><td colspan=\"3\"><em>although listing further MgSO4 might be arguably helpful, is not a substantial </em></td></tr><tr><td colspan=\"3\"><em>addition) </em></td></tr><tr><td></td><td>Antibiotics: Anaphylaxis</td><td></td></tr><tr><td colspan=\"3\">NO MARK</td></tr><tr><td></td><td>Continued inhaled bronchodilators (not an escalation)</td><td></td></tr><tr><td></td><td>Continued oxygen</td><td></td></tr><tr><td></td><td>Frusemide (would not be recommended at this stage)</td><td></td></tr><tr><td></td><td>Intubation (would not be recommended at this stage)</td><td></td></tr><tr><td colspan=\"3\">Needle thoracostomies (no evidence from stem, dangerous at this point)</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":2,"title":"","stemText":"A 78yo female presents with sudden onset, severe, Rt hip pain occurring whilst lying in bed. On exam she has no sensation in her Rt leg and cannot lift the effected limb off the bed. She has no femoral pulse on the effected side.","parts":[{"id":"a","label":"Part A","prompt":"Please list risk factors for Acute Limb Ischemia (5 marks)"},{"id":"b","label":"Part B","prompt":"Please describe the classical symptoms associated with Acute Arterial occlusion,\nincluding ( 6 marks)\n-Two Symptoms indicating a threatened limb: -Four other symptoms:"},{"id":"c","label":"Part C","prompt":"The patient receives IV analgesia and progresses for a CT Angiogram of her lower limbs, please describe the image below and answer the following questions (3 marks)"},{"id":"c2","label":"Part C","prompt":"Describe (3 marks)"},{"id":"d","label":"Part D","prompt":"What possible definitive treatments are options for this patient: (3 marks)"},{"id":"e","label":"Part E","prompt":"What treatment should be initiated whilst awaiting vascular review (3 marks)."}],"propPages":["asset:imgc92b76af7e3f99b80f"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Model Answer</div><div class=\"answer-line\">Atrial Fibrillation (1)</div><div class=\"answer-line\">Recent AMI (1)</div><div class=\"answer-line\">Aortic atherosclerosis (1)</div><div class=\"answer-line\">Large vessel aneurysmal disease (1)</div><div class=\"answer-line\">DVT (1)</div><div class=\"answer-line\">HTN (1)</div><div class=\"answer-line\">Prior lower limb revascularisation (1)</div><div class=\"answer-line\"><strong>b. (6 marks) </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">__________________________________________________</div><div class=\"answer-line\">__________________________________________________</div><div class=\"answer-line\">__________________________________________________</div><div class=\"answer-line\">__________________________________________________</div><div class=\"answer-line\">__________________________________________________</div><div class=\"answer-line\">Model Answer</div><div class=\"answer-line\">Atrial Fibrillation (1)</div><div class=\"answer-line\">Recent AMI (1)</div><div class=\"answer-line\">Aortic atherosclerosis (1)</div><div class=\"answer-line\">Large vessel aneurysmal disease (1)</div><div class=\"answer-line\">DVT (1)</div><div class=\"answer-line\">HTN (1)</div><div class=\"answer-line\">Prior lower limb revascularisation (1)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>b. (6 marks) </strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><strong>Two Symptoms indicating a threatened limb </strong></div><div class=\"answer-line\">_________________________________________________</div><div class=\"answer-line\">_________________________________________________</div><div class=\"answer-line\"><strong>Four other symptoms </strong></div><div class=\"answer-line\">_________________________________________________</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">_________________________________________________</div><div class=\"answer-line\">_________________________________________________</div><div class=\"answer-line\">_________________________________________________</div><div class=\"answer-line\">Model answer</div><div class=\"answer-line\">6 ‘Ps’; Pain / Pallor / Pulselessness / Perishingly cold / *parasthesia / *paralysis. *Indicates</div><div class=\"answer-line\">threatened limb</div><div class=\"answer-line\"><strong>c. The patient receives IV analgesia and progresses for a CT Angiogram of her lower </strong></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"answer-line\"><strong>Image 1 </strong></div><div class=\"answer-line\">__________________________________________________</div><div class=\"answer-line\">__________________________________________________</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":3,"title":"","stemText":"A 79 year old female is intubated in your ED after a deliberate overdose of temazepam.","parts":[{"id":"a","label":"Part A","prompt":"State 4 challenges specific to intubation of the older patient in the ED and how you\nwould modify your approach for them (8 marks)"},{"id":"b","label":"Part B","prompt":"Shortly after intubation, the patient becomes hypotensive to 70/43. Her SpO2 remains 100%. List 4 possible causes for this (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Limited neck mobility or cervical spine</div><div class=\"answer-line\">Ramped positioning</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Poor respiratory reserve → rapid</div><div class=\"answer-line\">Ensure prolonged preoxygenation</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":4,"title":"","stemText":"A 67 year old female is brought into ED with a 3-day history of vomiting and abdominal\npain. Her initial VBG has been provided. (12 marks)\n\npH 6.88\n\npCO2 27.2 mmHg (40 - 50 mmHg)\n\npO2 35.3 mmHg (25 - 40 mmHg)\n\nNa 134 mmol (135 - 145 mmol)\n\nK 7.1 mmol (3.5 - 4.5 mmol)\n\nHCO3 5 mmol (22 - 26 mmol)\n\nCl 100 mmol (90 - 105 mmol)\n\nGlucose 29 mmol (4 - 8 mmol)\n\nLactate 4 mmol (<2 mmol)\n\nUrea 8 mmol (2 - 8 mmol)\nCreat 95 mmol (45 - 90 mmol)","parts":[{"id":"a","label":"Part A","prompt":"Interpret the acid-base abnormalities in the results provided and include any formulae that are used in calculations. (4 marks)"},{"id":"b","label":"Part B","prompt":"Provide a differential diagnosis for this presentation. (4 marks)"},{"id":"c","label":"Part C","prompt":"Her ketones are recorded as 6.0. State your immediate management priorities. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">1</div><div class=\"answer-line\">AG: Na – (Cl + HCO₃⁻) = 134 – (100 + 5) = 29</div><div class=\"answer-line\">1</div><div class=\"answer-line\">DR: (AG – 12) ÷ (24 – HCO₃⁻) = (29 – 12)/(19) ≈ 0.9</div><div class=\"answer-line\">0.5</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">HCO3 5 mmol (22 – 26 mmol)</div><div class=\"answer-line\">Cl 100 mmol (90 – 105 mmol)</div><div class=\"answer-line\">Glucose 29 mmol (4 – 8 mmol)</div><div class=\"answer-line\">Lactate 4 mmol (&lt;2 mmol)</div><div class=\"answer-line\">Urea 8 mmol (2 – 8 mmol)</div><div class=\"answer-line\">Creat 95 mmol (45 – 90 mmol)</div><div class=\"answer-line\">Severe High Anion Gap Metabolic Acidosis</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">1</td></tr><tr><td>AG: Na – (Cl + HCO₃⁻) = 134 – (100 + 5) = 29</td><td>1</td></tr><tr><td>DR: (AG – 12) ÷ (24 – HCO₃⁻) = (29 – 12)/(19) ≈ 0.9</td><td>0.5</td></tr><tr><td>Inadequate respiratory compensation</td><td>0.5</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":5,"title":"","stemText":"A 75-year-old female presents to your urban district emergency department with 24-hours of intermittent light-headedness. She has a history of sick-sinus syndrome which required the implantation of a permanent pacemaker only six days earlier. On assessment she is alert and oriented with a strong irregular radial pulse at 84 beats per minute. Her blood pressure is 146/84 without a postural drop and her remaining vital signs are within normal limits.\nHere is the initial 12-lead ECG.","parts":[{"id":"a","label":"Part A","prompt":"Describe and interpret his ECG (4 marks)."},{"id":"b","label":"Part B","prompt":"List FOUR mechanisms by which a pacemaker can malfunction (4 marks)."},{"id":"c","label":"Part C","prompt":"What are TWO imaging modalities you can use to further investigate this problem and why you would use them? (2 marks). A junior member of your team enquires about the role of magnet in these circumstances."},{"id":"d","label":"Part D","prompt":"What is the expected outcome of placing a magnet over a pacemaker? (TWO marks)"}],"propPages":["asset:img549e44bad669d4c37e"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Irregularly irregular QRS, ~84bpm</td></tr><tr><td></td><td>Evidence of both atrial &amp; ventricular pacing</td></tr><tr><td></td><td>Atrial-pacing followed by P-wave (normal capture)</td></tr><tr><td></td><td><strong>Sporadic/inappropriate Ventricular pacing spikes with failure to capture</strong></td></tr><tr><td colspan=\"2\">Dual-lead pacemaker with under-sensing &amp; failure to capture, suggestive of a right-</td></tr><tr><td colspan=\"2\">ventricular lead fault.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">1. Failure to capture</div><div class=\"answer-line\">a.</div><div class=\"answer-line\"><strong>Lead displacement </strong></div><div class=\"answer-line\">b. Lead fracture</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Battery depletion</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>i.</td><td>Ischaemia</td></tr><tr><td>ii.</td><td>Electrolyte/metabolic (esp. hyperkalaemia)</td></tr><tr><td>iii.</td><td>Drugs (esp. Class III anti-arrhythmics)</td></tr><tr><td colspan=\"2\">2. Inappropriate sensing</td></tr><tr><td colspan=\"2\">3. Inappropriate PPM rate</td></tr><tr><td>a.</td><td>Pacemaker-mediated tachycardia</td></tr><tr><td colspan=\"2\">b. Runaway pacemaker</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":6,"title":"","stemText":"An 80 year old man from home presents following a syncopal episode. His vital signs are:\n\nHR\n\nBP\n140/80\n\nRR\n\nSats\n98% on room air\n\nBSL\n\nGCS","parts":[{"id":"a","label":"Part A","prompt":"List 3 relevant findings on his ECG other than rate (3 marks)"},{"id":"b","label":"Part B","prompt":"List 3 relevant elements to ask on history (3 marks)"},{"id":"c","label":"Part C","prompt":"List 5 possible causes of his tachycardia (5 marks)"}],"propPages":["asset:img9400fca44f877bd088"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">LBBB &amp; LAD</div><div class=\"answer-line\">PVC</div><div class=\"answer-line\">Normal ST segments</div><div class=\"answer-line\">Normal T waves</div><div class=\"answer-line\">Normal QT</div><div class=\"answer-line\">Prolonged PR</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Injuries sustained during syncope</div><div class=\"answer-line\">Advanced care directives</div><div class=\"answer-line\">Chest pain</div><div class=\"answer-line\">He has a permanent pacemaker inserted and is discharged from the ward the next day. 2 days</div><div class=\"answer-line\">later he represents feeling unwell with a heart rate of 120.</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Supraventricular / atrial tachycadia (underlying sick sinus / tach-brady)</div><div class=\"answer-line\">Pacemaker mediated tachycardia</div><div class=\"answer-line\">Sepsis due to nosocomial infection</div><div class=\"answer-line\">PE related to recent hospitalisation / recuperation from procedure</div><div class=\"answer-line\">Hypovolaemia – blood loss from injury from syncope (this is a stretch!!) / not drinking while</div><div class=\"answer-line\">admitted and fasting / new diuretics- these are all a bit far fetched. Maybe just 4??</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":7,"title":"","stemText":"A 38 year old male presents with 3 hour history of right sided facial weakness.","parts":[{"id":"a","label":"Part A","prompt":"What clinical exam finding would suggest this is a LMN issue rather than an UMN issue? (1 mark)"},{"id":"b","label":"Part B","prompt":"You are confident from your clinical exam this is a LMN nerve palsy. Other than a bells palsy, name 6 different causes for this? (6 marks)"},{"id":"c","label":"Part C","prompt":"You suspect he has a bells palsy, what are your discharge instructions? (2 marks)"},{"id":"d","label":"Part D","prompt":"After recovery from a facial nerve palsy, aberrant regeneration of the nerve can cause what adverse effects? (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">UMN lesion spares the forehead allowing eyebrow movement while a LMN lesion paralyzes the</div><div class=\"answer-line\">entire side of the face including the forehead</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>-Brainstem (pons)</td><td>Stroke, demyelination (MS), tumour</td></tr><tr><td>-Cerebello-pontine angle</td><td>Acoustic neuroma, meningioma, meningitis</td></tr><tr><td>-Middle ear</td><td>Infections, tumours (affects chorda tympani)</td></tr><tr><td>-Trauma</td><td>Petrous temporal bone fracture, penetrating nerve trauma</td></tr><tr><td>-Infections</td><td>Bell’s palsy, Ramsay-Hunt syndrome (HZV), tetanus, tick paralysis</td></tr><tr><td>-Parotid gland</td><td>Tumour, abscess, trauma/surgery</td></tr><tr><td>-Rare mononeuritis</td><td>Connective tissue disease, diabetes, alcohol, paraneoplastic, sarcoidosis, HIV</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Prednisolone 1mg/kg PO up to 75mg daily for 5 days</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Artificial tear drops and Protective eye pads for corneal ulceration risk</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Psychological Support- may be needed due to the disfiguring nature of the lesion</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Synkinesis (co-contraction of facial muscles)</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Crocodile tears (Involuntary tearing of the eye on the affected side when eating)</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Gustatory sweating</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":8,"title":"","stemText":"You are the ED consultant in a tertiary hospital. 78 year old woman presents with SOB and dizziness, following a syncope. She has recently been unwell with a flu like illness which was managed in the community.\n\nT: 37.3\n\nHR 120\n\nBP 100/ 60\n\nRR 28\nO2 98% on 6L Hudson mask.\nYou are concerned for pulmonary embolism.","parts":[{"id":"a","label":"Part A","prompt":"List 3 other differential diagnoses for this presentation (3 marks)."},{"id":"b","label":"Part B","prompt":"Outline your management of this intermediate high risk PE (4 marks)."},{"id":"c","label":"Part C","prompt":"List two indications for systemic reperfusion therapy in PE (2 marks)?"},{"id":"d","label":"Part D","prompt":"List 3 clinical features that confer higher risk of mortality from PE (3 marks)?"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Pneumonia</td></tr><tr><td></td><td>Cardiac failure</td></tr><tr><td colspan=\"2\">Exacerbation of underlying CCF</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td colspan=\"2\">Myocarditis</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td colspan=\"2\">Arrythmia (e.g. AF)</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td></td><td>Trauma following syncope (contusions/ haemothroax).</td></tr><tr><td colspan=\"2\">Mobile CXR does not demonstrate clear cause for her respiratory distress.</td></tr><tr><td colspan=\"2\">CTPA demonstrates multiple bilateral pulmonary emboli with significant clot burden as well</td></tr><tr><td colspan=\"2\">as evidence of right heart strain. Her troponin is 700ngl/L.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">2.  Assess IVC with POCUS and judicious fluid resuscitation aiming for MAP &gt;</td></tr><tr><td colspan=\"2\">65mmHg.</td></tr><tr><td colspan=\"2\">3. Early use of vasopressors eg noradrenaline 0.01mcg/kg/min aiming MAP &gt;</td></tr><tr><td colspan=\"2\">65mmHg.</td></tr><tr><td colspan=\"2\">4. Admit to ICU for monitoring and consideration of reperfusion <strong>only if deteriorates.</strong></td></tr><tr><td></td><td>Continue anticoagulation.</td></tr><tr><td></td><td><strong>Not for systemic thrombolysis in intermediate risk</strong> according to ESC guidelines-</td></tr><tr><td colspan=\"2\">also increased risk of bleeding given age &gt; 75 years- unless deteriorates (see below)</td></tr><tr><td></td><td>Consideration should be given to targeted (catheter directed) thrombolysis/</td></tr><tr><td colspan=\"2\">embolectomy (eTG). Emerging evidence also for ‘low dose’/ half dose’ systemic</td></tr><tr><td colspan=\"2\">thrombolysis (10mg followed by 40mg alteplase) for intermediate high risk patients</td></tr><tr><td colspan=\"2\">first trialled in MOPPET with intention to reduce the risk of CV collapse.</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Obstructive shock</div><div class=\"answer-line\"></div><div class=\"answer-line\">Systolic &lt; 90mmHg or</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">vasopressors required to keep SBP &gt; 90mmHg despite adequate filling</div><div class=\"answer-line\">o</div><div class=\"answer-line\">+ End organ hypoperfusion</div><div class=\"answer-line\">Persistent hypotension</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":9,"title":"","stemText":"A 32-year-old female presents with a headache for 3 days. She has some loss of vision and\ndescribes bright lines in her visual field.","parts":[{"id":"a","label":"Part A","prompt":"List the characteristics that are used to diagnose migraine with aura (3 marks)"},{"id":"b","label":"Part B","prompt":"Other than migraine with aura, list 5 differential diagnoses for headache with visual change (5 marks)"},{"id":"c","label":"Part C","prompt":"Outline an escalating approach to the pharmacological treatment of severe migraine including doses (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Headache lasting 4-72 hours</div><div class=\"answer-line\"></div><div class=\"answer-line\">At least two of - pain is unilateral, throbbing, moderate/severe, aggravated by</div><div class=\"answer-line\"></div><div class=\"answer-line\">activity</div><div class=\"answer-line\">At least one of - associated nausea/vomiting, photophobia, phonophobia</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">At least two of - pain is unilateral, throbbing, moderate/severe, aggravated by</div><div class=\"answer-line\"></div><div class=\"answer-line\">activity</div><div class=\"answer-line\">At least one of - associated nausea/vomiting, photophobia, phonophobia</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"></div><div class=\"answer-line\">Transient visual or sensory symptoms</div><div class=\"answer-line\"></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":10,"title":"","stemText":"A 54 year old female is brought in by ambulance to your tertiary ED following a sudden\n• nset headache. On arrival to the ED, she has a GCS of 7 with reactive and equal pupils\nbilaterally and otherwise normal vital signs. She undergoes an uncomplicated intubation. An axial slice of her CT brain is below.","parts":[{"id":"a","label":"Part A","prompt":"State 2 findings on this image of the CT scan (2 marks)"},{"id":"b","label":"Part B","prompt":"List 5 neuroprotective measures you will take for this patient (5 marks)"},{"id":"c","label":"Part C","prompt":"While awaiting Neurosurgical team review, the patient becomes hypertensive to 205/100 with a HR of 39. Her other vital signs are unchanged. State the underlying issue and outline your actions to address this (5 marks)"}],"propPages":["asset:img1ad4393af492969d63"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Subarachnoid haemorrhage + one other</div><div class=\"answer-line\"></div><div class=\"answer-line\">Blood in basal cisterns/Sylvian fissure</div><div class=\"answer-line\">o</div><div class=\"answer-line\">Sulcal effacement</div><div class=\"answer-line\">o</div><div class=\"answer-line\">No midline shift</div><div class=\"answer-line\">o</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Oxygenation: aim SpO2 &gt;94%</td></tr><tr><td></td><td>Ventilation:</td></tr><tr><td colspan=\"2\">Maintain CO2 35 – 40</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td colspan=\"2\">Maintain ventilator synchrony, adequate sedation</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td></td><td>Normotension:</td></tr><tr><td colspan=\"2\">Many different targets depending on text, but generally SBP 120 – 160 (Tintinalli)</td></tr><tr><td colspan=\"2\">o</td></tr><tr><td></td><td>Positioning: HOB 30 degrees</td></tr><tr><td></td><td>Normoglycaemia BSL 6 – 10</td></tr><tr><td></td><td>Normothermia temp &lt;38 degrees</td></tr><tr><td></td><td>Eunatraemia</td></tr><tr><td></td><td>ETT tape instead of tie</td></tr><tr><td colspan=\"2\"><strong>c.While awaiting Neurosurgical team review, the patient becomes hypertensive to </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Underlying issue: Cushing’s reflex – significantly raised ICP/imminent brain</div><div class=\"answer-line\"></div><div class=\"answer-line\">herniation</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":11,"title":"","stemText":"A 78-year-old female presents to the Emergency Department following a fall at home. She\nstruck her head on the corner of a table. On arrival she is alert (GCS 15). She has a 10 cm scalp laceration with ongoing bleeding. She is on apixaban for atrial fibrillation.\nHer observations are HR 92 bpm, BP 150/82 mmHg, RR 16, SpO2 98% on room air.","parts":[{"id":"a","label":"Part A","prompt":"Describe your specific approach to haemostasis in this patient’s scalp laceration, including local and systemic considerations. (4 marks)"},{"id":"b","label":"Part B","prompt":"Outline the indications for reversal of apixaban in this patient. (4 marks)"},{"id":"c","label":"Part C","prompt":"What are the available options for anticoagulant reversal in this patient, and what is your preferred option? Provide justification. (2 marks)"},{"id":"d","label":"Part D","prompt":"List two potential complications of reversal therapy. (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Local haemostatic adjuncts (e.g. gelatin sponge, topical TXA) (1 mark)</div><div class=\"answer-line\"></div><div class=\"answer-line\">Systemic measures: tranexamic acid, correction of coagulopathy, maintain</div><div class=\"answer-line\"></div><div class=\"answer-line\">normothermia and haemodynamics (1 mark)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Life-threatening or uncontrolled bleeding</div><div class=\"answer-line\"></div><div class=\"answer-line\">Bleeding into a critical site (e.g. intracranial, spinal, intraocular)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"></div><div class=\"answer-line\">normothermia and haemodynamics (1 mark)</div><div class=\"answer-line\"><strong>Marking guide (1 mark each): </strong></div><div class=\"answer-line\">Life-threatening or uncontrolled bleeding</div><div class=\"answer-line\"></div><div class=\"answer-line\">Bleeding into a critical site (e.g. intracranial, spinal, intraocular)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\"></div><div class=\"answer-line\">Haemodynamic instability due to bleeding</div><div class=\"answer-line\"></div><div class=\"answer-line\">Requirement for urgent neurosurgical (or other surgical) intervention</div><div class=\"answer-line\"></div><div class=\"answer-line\"><em>(Any 4 valid = 0.5 marks) </em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":12,"title":"","stemText":"A 40-year-old male presents to the Emergency Department from the airport having admitted\nto being a body packer. He proceeded to become agitated, complaining of chest pain and has a dilated right pupil with mild ptosis. His observations are:","parts":[{"id":"a","label":"Part A","prompt":"List 5 key investigations with justification (5 marks)"},{"id":"b","label":"Part B","prompt":"List 7 immediate management priorities (7 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">A 40-year-old male presents to the Emergency Department from the airport having admitted</div><div class=\"answer-line\">to being a body packer. He proceeded to become agitated, complaining of chest pain and has</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">HR: 160 bpm</div><div class=\"answer-line\"></div><div class=\"answer-line\">BP: 220/130 mmHg</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":13,"title":"","stemText":"A 54 year old known alcoholic with oesophageal varices has presented with haematemesis.\nShe is hemodynamically unstable with active bleeding. She is intubated in your resuscitation bay. You need to insert a Sengstaken-Blakemore tube.","parts":[{"id":"a","label":"Part A","prompt":"Describe the method of insertion. (5 marks)"},{"id":"b","label":"Part B","prompt":"List 3 potential complications from the insertion of this piece of equipment (3 marks)\nHer medical management will include a terlipressin or octreotide infusion."},{"id":"c","label":"Part C","prompt":"Explain how the mechanism of action of these drugs in the treatment of oesophageal bleeding. (2 marks)"},{"id":"d","label":"Part D","prompt":"List 2 other medical treatments you would commence specific to variceal bleeding. (2"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>Sensible approach to insertion. Starred steps should be included </em></div><div class=\"answer-line\">Supine with 45 degrees head up</div><div class=\"answer-line\">**Estimate length by bridge of nose to xiphoid process</div><div class=\"answer-line\">Check both balloons for leaks</div><div class=\"answer-line\">Lubricate balloons</div><div class=\"answer-line\">Insert via mouth via laryngoscopy into the oesophagus</div><div class=\"answer-line\">**Confirm position on CXR – gastric balloon in stomach</div><div class=\"answer-line\">**Inflate gastric balloon using 50ml increments up to 250-300ml with air</div><div class=\"answer-line\">Fix securely with traction and rope pulley system with 500mL bag of fluid</div><div class=\"answer-line\">Inflation of oesophageal balloon usually not required – use if continued bleeding despite an</div><div class=\"answer-line\">adequately inflated gastric balloon</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Painful / uncomfortable (less relevant for this patient as intubated)</div><div class=\"answer-line\">Aspiration (again less relevant in intubated patient)</div><div class=\"answer-line\">Pressure necrosis (do not leave in situ for more than 24 hours)</div><div class=\"answer-line\">Oesophageal perforation</div><div class=\"answer-line\">Acute upper airway obstruction due to balloon migration (again, not that common in</div><div class=\"answer-line\">intubated patients)</div><div class=\"answer-line\">Cardiac arrhythmias</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><em>Sensible approach to insertion. Starred steps should be included </em></div><div class=\"answer-line\">Supine with 45 degrees head up</div><div class=\"answer-line\">**Estimate length by bridge of nose to xiphoid process</div><div class=\"answer-line\">Check both balloons for leaks</div><div class=\"answer-line\">Lubricate balloons</div><div class=\"answer-line\">Insert via mouth via laryngoscopy into the oesophagus</div><div class=\"answer-line\">**Confirm position on CXR – gastric balloon in stomach</div><div class=\"answer-line\">**Inflate gastric balloon using 50ml increments up to 250-300ml with air</div><div class=\"answer-line\">Fix securely with traction and rope pulley system with 500mL bag of fluid</div><div class=\"answer-line\">Inflation of oesophageal balloon usually not required – use if continued bleeding despite an</div><div class=\"answer-line\">adequately inflated gastric balloon</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Haemorrhage</div><div class=\"answer-line\">Painful / uncomfortable (less relevant for this patient as intubated)</div><div class=\"answer-line\">Aspiration (again less relevant in intubated patient)</div><div class=\"answer-line\">Pressure necrosis (do not leave in situ for more than 24 hours)</div><div class=\"answer-line\">Oesophageal perforation</div><div class=\"answer-line\">Acute upper airway obstruction due to balloon migration (again, not that common in</div><div class=\"answer-line\">intubated patients)</div><div class=\"answer-line\">Cardiac arrhythmias</div><div class=\"answer-line\"><strong>Her medical management will include a terlipressin or octreotide infusion. </strong></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":14,"title":"","stemText":"You are the FACEM in charge working in a tertiary emergency department. A 37 year old woman is brought in by ambulance, paramedics have ceased her generalised tonic-clonic seizure at home with IV midazolam. She is not known to have had seizures before, but her husband informs paramedics she is 35 weeks pregnant. You note her vital observations as follows:\n\nHR = 115/min, BP 195/110, Sats 100% NRBM O2, RR 22, T 36.8, BSL 7.2","parts":[{"id":"a","label":"Part A","prompt":"List 3 diagnostic criteria for pre-eclampsia (3 marks):"},{"id":"b","label":"Part B","prompt":"Besides eclampsia, list 4 other potential causes of her seizure and their specific emergency treatments (4 marks each)"},{"id":"c","label":"Part C","prompt":".She starts having a generalised seizure again. List your management priorities now (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">a.</div><div class=\"answer-line\">Hypertension after 20/40 gestation: SBP&gt;160 DBP&gt;110 (1 mark - mandatory) AND</div><div class=\"answer-line\">(further 2 marks for any below)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">- 300 mg or more per 24 hour urine collection (or this amount extrapolated from a</div><div class=\"answer-line\">timed collection)</div><div class=\"answer-line\">- Protein/creatinine ratio of 0.3 mg/dL or more</div><div class=\"answer-line\">- Dipstick reading of 2+ (used only if other quantitative methods not available)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td>OR</td><td>in the absence of proteinuria, new-onset hypertension with the new onset of any</td></tr><tr><td colspan=\"2\">of the following: (1 mark)</td></tr><tr><td>i.</td><td>Thrombocytopenia: Platelet count less than 100,000 3 109/L</td></tr><tr><td>ii.</td><td>Renal insufficiency: Serum creatinine concentrations greater than 1.1 mg/dL or a</td></tr><tr><td colspan=\"2\">doubling of the serum creatinine concentration in the absence of other renal disease</td></tr><tr><td>iii.</td><td>Impaired liver function: Elevated blood concentrations of liver transaminases to twice</td></tr><tr><td colspan=\"2\">normal concentration</td></tr><tr><td>iv.</td><td>Pulmonary edema</td></tr><tr><td>v.</td><td>New-onset headache unresponsive to medication and not accounted for by alternative</td></tr><tr><td colspan=\"2\">diagnoses or visual changes</td></tr><tr><td>vi.</td><td>Visual symptoms</td></tr><tr><td colspan=\"2\">FROM  LATEST RANZCOG GUIDELINES 2020</td></tr><tr><td colspan=\"2\"><strong>b.Besides eclampsia, list 4 other potential causes of her seizure and their specific </strong></td></tr><tr><td colspan=\"2\"><strong>emergency treatments (4 marks each) </strong></td></tr><tr><td colspan=\"2\">Cause (0.5 mark) PLUS Treatment – name/dose/route(0.5 mark) = 1 mark each</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":15,"title":"","stemText":"You have been sent to a music festival as part of a deployed hospital team. A 27-year-old female was found collapsed - her friends carried her to the festival medical tent and stated that she had been taking MDMA. Her vital signs are:\n\nHR 190 bpm\nSBP 200/- mmHg\n\nRR 50 Sats 91%\n\nTemp 42.5\n\nGCS 9\nShe was given midazolam 5mg IV, 0.9% saline 1L commenced and had cold packs applied to\naxillae and groins. She is becoming agitated, combative and difficult to restrain. A VBG shows\n\npH 7.08\n\npCO2 75\n\npO2 ....\n\nLactate 9.6\nBicarb 9\n\nCreatinine 190\n\nK 6.8","parts":[{"id":"a","label":"Part A","prompt":"Outline, with explanation, the critical findings (3 marks)"},{"id":"b","label":"Part B","prompt":"List 3 medications (with doses) that could be used in controlling agitation in this\ncase (3 marks)"},{"id":"c","label":"Part C","prompt":"Describe in detail how you would manage this patient’s marked hyperthermia (6 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Profound metabolic acidosis - high lactate, low bicarb</div><div class=\"answer-line\"></div><div class=\"answer-line\">Respiratory acidosis  - expected CO2 should be low - likely inadequate ventilatory</div><div class=\"answer-line\"></div><div class=\"answer-line\">response to acidaemia (despite increased RR)</div><div class=\"answer-line\">Hyperkalaemia - dangerously high - likely a result of acidosis and AKI</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Benzodiazepines - midazolam 5-10mg IV (or IM) repeat every 5 minutes (other</div><div class=\"answer-line\"></div><div class=\"answer-line\">benzos might be acceptable though not oral in this context)</div><div class=\"answer-line\">Ketamine 1mg/kg IV or 4mg/kg IM</div><div class=\"answer-line\"></div><div class=\"answer-line\">Droperidol 10mg IM</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Answer must include aspects of both decreasing heat production and active cooling</div><div class=\"answer-line\">Decrease heat production. Urgent, aggressive, escalating sedation – benzos → ketamine or</div><div class=\"answer-line\">droperidol → progress to RSI especially given low GCS</div><div class=\"answer-line\">Active cooling. Simple measures (ice packs groin/axillae) have already commenced – answer</div><div class=\"answer-line\">needs to move beyond these and ideally escalate thru increasingly aggressive measures. Aim</div><div class=\"answer-line\">is &lt; 38.5 in 30 minutes. Several possibilities</div><div class=\"answer-line\">Ice slurry in large bags – pack torso &amp; limbs. Or wrapping in a tarp filled with ice</div><div class=\"answer-line\"></div><div class=\"answer-line\">slurry (ice taco)</div><div class=\"answer-line\">Evaporative cooling – patient stripped (covering with wet towels or sheets insulates</div><div class=\"answer-line\"></div><div class=\"answer-line\">from the cooling effect of evaporation), tepid mist/spray, fan at foot end or side</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":16,"title":"","stemText":"A 52 year old male presents with an acute red left eye.","parts":[{"id":"a","label":"Part A","prompt":"List 4 historical factors which may indicate more serious pathology (4 marks)"},{"id":"b","label":"Part B","prompt":"You diagnose acute angle closure glaucoma.\nName 4 drugs used to treat this condition with mechanism of action or effect. Doses not\nnecessary (8 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Pain (as opposed to irritation)</td></tr><tr><td></td><td>Reduced vision</td></tr><tr><td></td><td>Contact lens use</td></tr><tr><td></td><td>Foreign body exposure history (in particular any possibility of penetrating injury)</td></tr><tr><td></td><td>Known connective tissue disorders, e.g. risk of keratitis, iritis/uveitis, epi/scleritis and</td></tr><tr><td colspan=\"2\">giant cell arteritis</td></tr><tr><td colspan=\"2\">Other reasonable answers acceptable. Must be historical, not examination or investigation.</td></tr><tr><td colspan=\"2\"><strong>b.You diagnose acute angle closure glaucoma. </strong></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Timolol drops: reduce aqueous humour production</td></tr><tr><td></td><td>Pilocarpine drops: muscarinic agonist, increases aqueous humour outflow</td></tr><tr><td></td><td>Apraclonidine drops: reduces aqueous humour production and increases uveoscleral</td></tr><tr><td colspan=\"2\">outflow</td></tr><tr><td></td><td>Acetazolamide: reduces aqueous humour production</td></tr><tr><td></td><td>Analgesic option eg paracetamol</td></tr><tr><td colspan=\"2\">Anti-emetic option eg ondanseton</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":17,"title":"","stemText":"A young female is brought in by ambulance to your emergency department from a festival. She is believed to have inhaled isobutyl nitrite or ‘poppers’. She does have have blue- coloured skin and you suspect methemoglobinaemia","parts":[{"id":"a","label":"Part A","prompt":"Apart from inhaled isobutyl nitrite list 4 others potential causes of methemoglobinaemia (5 marks)"},{"id":"b","label":"Part B","prompt":"List 4 other signs or symptoms this patient could be experiencing that would suggest\nmethemoglobinaemia? (3 marks)"},{"id":"c","label":"Part C","prompt":"You decide to treat her with methylene blue. How does this treatment work for this condition? (2 marks)"},{"id":"d","label":"Part D","prompt":"There are multiple reasons for the failure of Methylene Blue. List 2 things you should consider if MetHb levels do not fall despite the treatment with methylene blue (2 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Congenital – cytochrome b5 reductase deficiency, haemoglobin M disease</div><div class=\"answer-line\">Acquired (toxin / drugs) – aniline dyes, benzene derivatives, chloroquine, dapsone, prilocaine</div><div class=\"answer-line\">/ lidnocaine, metoclopramide, nitrites, sulphonamides, trimethorprim</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">SpO2 reading 85-90% - THIS IS ESSENTIAL ANSWER. Cannot score full 4 marks without</div><div class=\"answer-line\">this.</div><div class=\"answer-line\">Cyanosis</div><div class=\"answer-line\">Symptoms and signs of decreased oxygen delivery (chest pain, dyspnoea, altered mental</div><div class=\"answer-line\">state, end organ damage)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">It restores the iron in the haemoglobin to its normal (reduced) oxygen-carrying state. Ferric</div><div class=\"answer-line\">state (Fe 3+) to ferrous ion (Fe 2+)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Facilitates the reduction of MetHb via the NADPH-dependent pathway.</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":18,"title":"","stemText":"A 27 y.o female presents with vomiting in pregnancy. She is currently 7 weeks gestation\nbased off LMP. This is her third presentation to emergency for vomiting and anorexia.","parts":[{"id":"a","label":"Part A","prompt":"Give 2 risk factors for hyperemesis gravidarum? (2 marks)"},{"id":"b","label":"Part B","prompt":"List and justify 4 investigations that you would perform for this patient (4 marks)"},{"id":"c","label":"Part C","prompt":"She continues to vomit despite oral antiemetics. List 3 medications that you might use including doses to help manage her symptoms. (3 marks)"},{"id":"d","label":"Part D","prompt":"The patient asks you if all these medications are safe to use in pregnancy. Fill in the table regarding drug classes in pregnancy. (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Molar pregnancy</td></tr><tr><td></td><td>Multiple pregnancy</td></tr><tr><td></td><td>Hx motion sickness, hyperemesis</td></tr><tr><td colspan=\"2\">Fam hx hyperemesis</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>EUC – hyponatraemia, hypokalaemia, AKI</td></tr><tr><td></td><td>Vbg - hypochloraemic metabolic alkalosis, hypoglycaemia</td></tr><tr><td></td><td>BSL, Ketones</td></tr><tr><td></td><td>TFT – precipitated by hyperthyroidism in pregnancy or can have hyperemesis</td></tr><tr><td colspan=\"2\">associated hyperthyroidism</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>BSL, Ketones</td></tr><tr><td></td><td>TFT – precipitated by hyperthyroidism in pregnancy or can have hyperemesis</td></tr><tr><td colspan=\"2\">associated hyperthyroidism</td></tr><tr><td></td><td>LFT, lipase – can have mild bili rise with hyperemesis.  Look for alternative causes</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">for symptoms</div><div class=\"answer-line\">UA – ketones, SG, UTI</div><div class=\"answer-line\"></div><div class=\"answer-line\">USS – multipregnancy, molar pregnancy</div><div class=\"answer-line\"></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":19,"title":"","stemText":"A 26 year old male is brought in by ambulance to your ED agitated and paranoid.","parts":[{"id":"a","label":"Part A","prompt":"State 4 differences between the features of drug induced psychosis and schizophrenia\n(4 marks) Features Drug induced psychosis Schizophrenia"},{"id":"b","label":"Part B","prompt":"Name 4 complications of chemical restraint in the ED (4 marks)"},{"id":"c","label":"Part C","prompt":"List 6 recommendations made by ACEM regarding restrictive practices in the ED (6\nmarks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Ref: Dunn</div><div class=\"answer-line\">Other reasonable answers acceptable – but must indicate differences, 1 point per difference.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>respiratory depression</td></tr><tr><td></td><td>pulmonary aspiration</td></tr><tr><td></td><td>sudden cardiac death</td></tr><tr><td></td><td>hypotension</td></tr><tr><td></td><td>DVT/PE</td></tr><tr><td></td><td>dystonic reactions</td></tr><tr><td></td><td>NMS</td></tr><tr><td></td><td>anticholinergic effects</td></tr><tr><td colspan=\"2\">delirium</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Summarised version from statement below:</td></tr><tr><td colspan=\"2\">5.1 Pre-hospital</td></tr><tr><td></td><td>Prefer health/ambulance transport; police only for safety support.</td></tr><tr><td></td><td>Expand community mental health responses to reduce ED presentations.</td></tr><tr><td colspan=\"2\">5.2 De-escalation</td></tr><tr><td></td><td>Prioritise respect, comfort, and communication.</td></tr><tr><td></td><td>Use restraint only as a last resort.</td></tr><tr><td></td><td>All ED staff should be trained in de-escalation.</td></tr><tr><td colspan=\"2\">5.3 Medications for Safe Assessment</td></tr><tr><td></td><td>Use only to enable assessment, not control.</td></tr><tr><td></td><td>Seek consent where possible; choose least-restrictive options.</td></tr><tr><td></td><td>Aim for calm, not sedation.</td></tr><tr><td colspan=\"2\">5.4 Physical or Mechanical Restraint</td></tr><tr><td></td><td>Only to prevent serious harm when all else fails.</td></tr><tr><td></td><td>Keep it brief, follow legal guidelines.</td></tr><tr><td colspan=\"2\">5.5 Seclusion</td></tr><tr><td></td><td>Avoid unless legally permitted and absolutely necessary.</td></tr><tr><td></td><td>Use only briefly and move patients out once safe.</td></tr><tr><td colspan=\"2\">5.6 Debriefing</td></tr><tr><td></td><td>Debrief patients and staff after incidents.</td></tr><tr><td></td><td>Use it to improve care and reduce future use.</td></tr><tr><td colspan=\"2\">5.7 Documentation and Reporting</td></tr><tr><td></td><td>Record what happened, why, and for how long.</td></tr><tr><td></td><td>Use standard templates to support review and accountability.</td></tr><tr><td colspan=\"2\">5.8 Design Principles and Alternative Models of Care</td></tr><tr><td></td><td>Create low-stimulus, calming ED environments.</td></tr><tr><td colspan=\"2\">Improve ED design to support de-escalation.</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":20,"title":"","stemText":"A 10 year old female is bitten by a snake while bushwalking. She attends your tertiary ED. She has a pressure immobilisation bandage (PIB) appropriately applied and her vital signs are within normal limits.","parts":[{"id":"a","label":"Part A","prompt":"State 5 features you would seek on examination of this patient (5 marks)"},{"id":"b","label":"Part B","prompt":"Describe the correct application technique for a pressure immobilisation bandage to a limb (3 marks)"},{"id":"c","label":"Part C","prompt":"List 2 indications for PIB removal (2 marks)"},{"id":"d","label":"Part D","prompt":"Name 3 other toxinological indications for pressure immobilisation bandage\napplication (3 marks)"},{"id":"e","label":"Part E","prompt":"Her father tells you she is afraid of hospitals and doctors. List 5 age-appropriate strategies to address this (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>Features of neurotoxicity: ptosis, extraocular muscle weakness (diplopia/blurred</td></tr><tr><td colspan=\"2\">vision), bulbar weakness (dysphagia), progressive respiratory muscle paralysis,</td></tr><tr><td colspan=\"2\">peripheral weakness</td></tr><tr><td></td><td>Features of myotoxicity: muscle tenderness or weakness</td></tr><tr><td></td><td>Features of coagulopathy: bleeding</td></tr><tr><td colspan=\"2\">Must include features from at least 2 categories</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Apply broad (15cm) elastic bandage over bite site and then entire limb (distal to</div><div class=\"answer-line\"></div><div class=\"answer-line\">proximal)</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"></div><div class=\"answer-line\">Must include features from at least 2 categories</div><div class=\"answer-line\">Apply broad (15cm) elastic bandage over bite site and then entire limb (distal to</div><div class=\"answer-line\"></div><div class=\"answer-line\">proximal)</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">Pressure should be firm, similar to applying bandage for sprained ankle</div><div class=\"answer-line\"></div><div class=\"answer-line\">Apply bandage as high as possible on the limb</div><div class=\"answer-line\"></div><div class=\"answer-line\">Immobilise limb with splint</div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"empty-state\">The supplied marking resource did not contain extractable text for this part.</div></section></div>","answerExtractionVerified":false,"answerSourceRetained":false},{"number":21,"title":"","stemText":"A 62-year-old male presents to your regional emergency department in North Queensland.\nHe was swimming this morning, within the stinger nets. Shortly after coming out of the water, he began to feel unwell with back, abdominal and limb pains. He did not notice anything bite or sting him in the water. The pain has intensified over the last 30 minutes, and he has now started to vomit. At time of triaging, he is writhing in pain, diaphoretic and nauseous with a blood pressure of 210/120, a heart rate of 124/min (regular), respiratory rate\n• f 24 and sats of 96% room air.\nHe has no significant PMHx, no known allergies and is on no regular medications.","parts":[{"id":"a","label":"Part A","prompt":"What is the most likely “syndrome” or cause of this patient’s symptoms (1 mark)"},{"id":"b","label":"Part B","prompt":"List 4 medications you would use to treat this patient’s symptoms: (4 marks)"},{"id":"c","label":"Part C","prompt":"Name 3 potentially life-threatening sequelae from this syndrome: (3 marks)"},{"id":"d","label":"Part D","prompt":"Despite initial treatment, 4 hours after arrival the patient continues to complain of pain and is becoming more breathless. He has moderate work of breathing, with a\nrespiratory rate of 30 and oxygen saturations on 2L nasal prongs of 88%. List 5\npotential reasons for this man’s dyspnoea: (5 marks)"},{"id":"e","label":"Part E","prompt":"List 5 investigations that are now indicated given the patients ongoing symptoms of\npain, cardiovascular instability and tachypnoea. (5 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><em>Answer 1 (Tintinalli, Cameron &amp; Toxicology Handbook) </em></div><div class=\"answer-line\"><em>Irukandji Syndrome </em></div><div class=\"answer-line\"></div><div class=\"answer-line\"><em>Carukia barnesi </em></div><div class=\"answer-line\"></div><div class=\"answer-line\"><em>Catecholamine release from jellyfish sting consistent with Irukandji </em></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><em>Suggested Answer 2 (Toxicology Handbook) </em></td></tr><tr><td></td><td><em><strong>Analgesia</strong></em><em>: IV fentanyl (0.5-1.0 microgram/kg/dose) repeated every 10 mins until </em></td></tr><tr><td colspan=\"2\"><em>appropriate analgesia achieved </em></td></tr><tr><td></td><td><em>Or IV morphine (0.1mg/kg) in titrated doses to effect </em></td></tr><tr><td></td><td><em><strong>Antiemetic:</strong></em><em> IV promethazine 25mg </em></td></tr><tr><td></td><td><em>Or IV ondansetron 4-8mg </em></td></tr><tr><td></td><td><em><strong>Antihypertensive:</strong></em><em> if ongoing hypertension despite opiate analgesia – IV Glyceryl </em></td></tr><tr><td colspan=\"2\"><em>trinitrate 50mg in 100ml 5% dextrose starting at 6ml/min titrated to achieve a </em></td></tr><tr><td colspan=\"2\"><em>systolic BP &lt;160mmHg </em></td></tr><tr><td></td><td><em><strong>Others: </strong></em><em>IV Magnesium Sulphate 10mmol for refractory pain and repeat if required, </em></td></tr><tr><td colspan=\"2\"><em>Oxygen to maintain sats &gt;92% </em></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\"><em>Suggested Answer 3 (Toxicology Handbook) </em></div><div class=\"answer-line\"><em>Cardiomyopathy </em></div><div class=\"answer-line\"></div><div class=\"answer-line\"><em>Cardiogenic shock </em></div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><em>Suggested Answer 2 (Toxicology Handbook) </em></td></tr><tr><td></td><td><em><strong>Analgesia</strong></em><em>: IV fentanyl (0.5-1.0 microgram/kg/dose) repeated every 10 mins until </em></td></tr><tr><td colspan=\"2\"><em>appropriate analgesia achieved </em></td></tr><tr><td></td><td><em>Or IV morphine (0.1mg/kg) in titrated doses to effect </em></td></tr><tr><td></td><td><em><strong>Antiemetic:</strong></em><em> IV promethazine 25mg </em></td></tr><tr><td></td><td><em>Or IV ondansetron 4-8mg </em></td></tr><tr><td></td><td><em><strong>Antihypertensive:</strong></em><em> if ongoing hypertension despite opiate analgesia – IV Glyceryl </em></td></tr><tr><td colspan=\"2\"><em>trinitrate 50mg in 100ml 5% dextrose starting at 6ml/min titrated to achieve a </em></td></tr><tr><td colspan=\"2\"><em>systolic BP &lt;160mmHg </em></td></tr><tr><td></td><td><em><strong>Others: </strong></em><em>IV Magnesium Sulphate 10mmol for refractory pain and repeat if required, </em></td></tr><tr><td colspan=\"2\"><em>Oxygen to maintain sats &gt;92% </em></td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part E</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><em>Suggested Answer 3 (Toxicology Handbook) </em></td></tr><tr><td></td><td><em>Cardiomyopathy </em></td></tr><tr><td></td><td><em>Cardiogenic shock </em></td></tr><tr><td></td><td><em>Pulmonary Oedema </em></td></tr><tr><td></td><td><em>Intracranial haemorrhage secondary to severe hypertension </em></td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":22,"title":"","stemText":"A 7-day-old female presents irritable and lethargic with persistent bilious vomiting. Mum\nreports a sudden onset with no associated diarrhoea. She had been tolerating feeds well and passed meconium at birth with subsequent normal stools.\n\nHR: 190 bpm\n\n\nBP: 80/45 mmHg\n\n\nRR: 65 breaths/min\n\n\nSpO2: 98% on room air\n\n\nTemp: 36.9°C\n An Abdominal XR is carried out.","parts":[{"id":"a","label":"Part A","prompt":"Describe and interpret this XR (2 marks) Decision is made to progress to CT:"},{"id":"b","label":"Part B","prompt":"Describe and interpret this CT (4 marks)"},{"id":"c","label":"Part C","prompt":"List 6 initial management steps (6 marks)"}],"propPages":["asset:imge68a5112150d2688af","asset:imgb9e8e45a45d497d696"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Describe: double bubble sign</div><div class=\"answer-line\"></div><div class=\"answer-line\">Interpret: midgut volvulus (or other cause of proximal obstruction not present at birth</div><div class=\"answer-line\"></div><div class=\"answer-line\">eg intususseption)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Air fluid levels – indicative of obstruction</div><div class=\"answer-line\"></div><div class=\"answer-line\">Whirlpool sign – indicative of volvulus</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td></td><td>IV access</td></tr><tr><td></td><td>Fluid resuscitation (10ml/kg)</td></tr><tr><td></td><td>Adequate analgesia (eg with doses)</td></tr><tr><td></td><td>NGT on free drainage</td></tr><tr><td></td><td>Keep NBM</td></tr><tr><td colspan=\"2\">Urgent Paeds surg consult</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":23,"title":"","stemText":"A 2-year-old child presents to your large metropolitan emergency department with a 2-hour\nhistory of stridor. There is obvious respiratory distress and biphasic stridor. She is currently accompanied by her grandmother who has limited English. Her observations are as follows\n\nRR 50 SpO2 98 HR 140 Temp 37.6","parts":[{"id":"a","label":"Part A","prompt":"Give 4 historical features that would allow you to establish differential diagnoses [4\nmarks]"},{"id":"b","label":"Part B","prompt":"She develops increasing respiratory distress. Her mum is now in attendance and expresses concern for a potential inhaled coin. She remains alert but now her cough seems to be ineffective. Outline your management [3 marks]"},{"id":"c","label":"Part C","prompt":"Despite your efforts, the child becomes unresponsive. Outline your immediate management including any intubation strategies which may be helpful [5 marks]"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>b.She develops increasing respiratory distress. Her mum is now in attendance and </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\"><strong>b.She develops increasing respiratory distress. Her mum is now in attendance and </strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">a.presence of fever/ urti/ infective symptoms – would not allow this to be the more than</td></tr><tr><td colspan=\"2\">one point – croup/ epig</td></tr><tr><td></td><td>Allergen exposure, urticaria, hx of allergy - anaphylaxis</td></tr><tr><td></td><td>Choking episode – inhaled FB</td></tr><tr><td></td><td>Un-immunised, lethargy, unwell  - bacterial trachietic or epiglottis</td></tr><tr><td></td><td>Neck stiffness , drooling, tortecullis – RPA</td></tr><tr><td></td><td>Swelling – neck of face – Ludwigs</td></tr><tr><td></td><td>Poor dentition – Ludwigs</td></tr><tr><td></td><td>Inhaled toxin</td></tr><tr><td colspan=\"2\">b. Call for help- ENT, anaesthetics</td></tr><tr><td colspan=\"2\">5 back blows  5 chest thrusts</td></tr><tr><td colspan=\"2\">Attempt FB removal with Macgills</td></tr><tr><td colspan=\"2\">c.Something alone the lines of</td></tr><tr><td colspan=\"2\">- PAEDS CODE BLUE , anaesthetics, ENT , team, resus ,</td></tr><tr><td colspan=\"2\">- commence CPR 15:2</td></tr><tr><td colspan=\"2\">- trial positive pressure</td></tr><tr><td colspan=\"2\">-  direct vision with macgills at ventilation, attempt to remove</td></tr><tr><td colspan=\"2\">- some reference to Fb above cords  &gt; FONA vs below cords – intubate down right main, pull</td></tr><tr><td colspan=\"2\">back ETT and place R side down to ventilate L lung</td></tr><tr><td colspan=\"2\">- ICU, transfer</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":24,"title":"","stemText":"A 82 year old male is BIBA septic with fever, tachycardia, hypotension,\ntachypnoea, delirium and a red groin rash. He has a history of T2DM.","parts":[{"id":"a","label":"Part A","prompt":"What are the top pathogens involved in necrotizing fasciitis? (4)"},{"id":"b","label":"Part B","prompt":"You examine the rash, what might you see clinically if this were necrotizing fasciitis? (5)"},{"id":"c","label":"Part C","prompt":"A CT is done. What are some of the features you may see on the CT if he has necrotizing fasciitis? (3)"},{"id":"d","label":"Part D","prompt":"What are the major principles of managing a necrotizing fasciitis? (6)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">Strep (especially strep A pyogenes)</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Aeromonas hydrophilia</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">-</div><div class=\"answer-line\">Vibrio species</div><div class=\"answer-line\">-</div><div class=\"answer-line\">Aeromonas hydrophilia</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"answer-line\">-</div><div class=\"answer-line\"><em>Bacteroides</em>, <em>Peptostreptococcus</em>,<em> Enterobacteriaceae</em></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":25,"title":"","stemText":"A 24 year old male presents to the ED with a 3 day history of worsening left eye redness, discharge and pain. He denies any sensation of a foreign body nor any visual disturbance. He is a contact lens wearer, but has no other ophthalmological history. His pupils are 3 mm and reaction. His slit lamp exam reveals no corneal defects and a normal anterior chamber.","parts":[{"id":"a","label":"Part A","prompt":"List 4 classes of infective conjunctivitis each with an example organism [4 marks]"},{"id":"b","label":"Part B","prompt":"Name 4 other non-infective differentials for the acute red eye with two differentiating features from above presentation [8 marks]"},{"id":"c","label":"Part C","prompt":"The patient clinically progresses with 10/10 pain, prolific purulent discharge and a fever Name\nyour 4 priorities in management of this condition [4 marks]"}],"propPages":["asset:img762e6f753ef49de3b0","asset:img37a6b22e8a74b47d19","asset:img455a6732da9d4027de","asset:img751a00bb106e2b186b"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\">A 24 year old male presents to the ED with a 3 day history of worsening left eye redness, discharge and</div><div class=\"answer-line\">pain. He denies any sensation of a foreign body nor any visual disturbance. He is a contact lens wearer,</div><div class=\"answer-line\">but has no other ophthalmological history.</div><div class=\"answer-line\">His pupils are 3 mm and reaction. His slit lamp exam reveals no corneal defects and a normal anterior</div><div class=\"answer-line\">chamber.</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">ANSWERS</div><div class=\"answer-line\">a.List 4 likely infective organisms for this conjunctivitis</div><div class=\"answer-line\">acute bacterial - <em>H. influenzae, S. pneumoniae, M. catarrhalis, S. aureus </em></div><div class=\"answer-line\">hyper acute bacterial - <em>N. gonococcus, N. meningitidis </em></div><div class=\"answer-line\">STI - chlamydial</div><div class=\"answer-line\">contact lens associated - <em>P. aeruginosa </em></div><div class=\"answer-line\">viral - adenovirus (includes epidemic keratoconjunctivitis - epiphoric +++)</div><div class=\"answer-line\">herpetic - HSV, VZV</div><div class=\"answer-line\">acute haemorrhagic viral - picornavirus, coxsackie</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">ANSWERS</div><div class=\"answer-line\">a.List 4 likely infective organisms for this conjunctivitis</div><div class=\"answer-line\">acute bacterial - <em>H. influenzae, S. pneumoniae, M. catarrhalis, S. aureus </em></div><div class=\"answer-line\">hyper acute bacterial - <em>N. gonococcus, N. meningitidis </em></div><div class=\"answer-line\">STI - chlamydial</div><div class=\"answer-line\">contact lens associated - <em>P. aeruginosa </em></div><div class=\"answer-line\">viral - adenovirus (includes epidemic keratoconjunctivitis - epiphoric +++)</div><div class=\"answer-line\">herpetic - HSV, VZV</div><div class=\"answer-line\">acute haemorrhagic viral - picornavirus, coxsackie</div><div class=\"answer-line\">b.Name 4 other differentials for the acute red eye and differentiating features</div><div class=\"answer-line\">non-infective  - allergic, toxic, chemical irritant</div><div class=\"answer-line\">acute glaucoma - abrupt onset of <em>severe pain (headache)</em> and vomiting, preceded by haloes,<em> fixed semi </em></div><div class=\"answer-line\"><em>dilated pupil</em>, hazy cornea, hx myopia, onset dim light</div><div class=\"answer-line\">uveitis - <em>photophobia</em>, floaters, reduced visual acuity, irregular pupils (miotic), flare &amp; cells, hypopyon,</div><div class=\"answer-line\">circumciliary injection (iritis), <em>associated autoimmune </em>arthritides, urethritis, IBD, haem malignancy; no</div><div class=\"answer-line\">discharge (but tearing)</div><div class=\"answer-line\">keratitis - dendritic ulcer (<em>recent HSV infection</em>), corneal abscess, subtarsal foreign body</div><div class=\"answer-line\">scleritis - very painful, may have reduced VA, <em>very tender globe</em>, underlying autoimmune condition (RA, SLE,</div><div class=\"answer-line\">AS, PsA, IBD, PAN), <em>deep blue inflammation </em></div><div class=\"answer-line\">episcleritis - painless or mild pain, normal vision, no discharge</div><div class=\"answer-line\">orbital cellulitis</div><div class=\"answer-line\">c.Name your priorities in management of this condition [4 marks]</div><div class=\"answer-line\">analgesia</div><div class=\"answer-line\">cover for gonococcal conjunctivitis - ceftriaxone 1-2g iv</div><div class=\"answer-line\">contrast enhanced CT orbits/sinus +/- brain</div><div class=\"answer-line\">urgent gram stain + other swabs</div><div class=\"answer-line\">eye lavage and dilating drops</div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":26,"title":"","stemText":"A 21 year old male has fallen 2 metres at a construction site onto an outstretched\nhand. He has presented to your Emergency Department and the following XR films have been taken. (12 marks)","parts":[{"id":"a","label":"Part A","prompt":"Identify the XR abnormality. (1 mark)"},{"id":"b","label":"Part B","prompt":"State your management priorities. (4 marks)"},{"id":"c","label":"Part C","prompt":"Which nerve is most commonly affected by this injury and what signs would you expect to see. (3 marks)"},{"id":"d","label":"Part D","prompt":"This patient was discharged without any management by a JMO on night shift and the XR report has been reviewed 2 days later. Outline your approach to this situation. (4 marks)"}],"propPages":["asset:img8f96c56c80240bc357"],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>c) Which nerve is most commonly affected by this injury and what signs would you </strong></div><div class=\"answer-line\"><strong>expect to see. (3 marks)</strong></div><div class=\"answer-line\"><strong>d) This patient was discharged without any management by a JMO on night shift </strong></div><div class=\"answer-line\"><strong>and the XR report has been reviewed 2 days later. Outline your approach to this </strong></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">have been taken. (12 marks)</div><div class=\"answer-line\"><strong>d) This patient was discharged without any management by a JMO on night shift </strong></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"answer-line\">Answers:</div></section><section class=\"answer-part\"><h5>Part D</h5><div class=\"empty-state\">The supplied marking resource did not contain extractable text for this part.</div></section></div>","answerExtractionVerified":false,"answerSourceRetained":false},{"number":27,"title":"","stemText":"A 3 week old female is brought into a regional emergency department with parental\nconcern for jaundice. (12 marks)","parts":[{"id":"a","label":"Part A","prompt":"Provide a differential diagnosis for the presentation and list features that you would ask in the history for each. (5 marks) Differential Diagnosis Historical feature"},{"id":"b","label":"Part B","prompt":"Other than bilirubin, list 6 investigations that you would perform. (3 marks)"},{"id":"c","label":"Part C","prompt":"Examination reveals a concerning scalp haematoma which is not consistent with the birth history. List risk factors for non-accidental injury. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><thead><tr><th>Item</th><th>Response / justification</th></tr></thead><tbody><tr><td>A 3 week old female is brought into a regional emergency department with parental</td><td>concern for jaundice. (12 marks)</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"answer-line\">Historical feature</div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">Answers:</td></tr><tr><td>a) Sepsis; history of fever</td><td>1</td></tr><tr><td>Haemolysis; birth trauma, ABO/Rhesus/Spherocytosis</td><td>1</td></tr><tr><td>Dehydration; urine output</td><td>1</td></tr><tr><td>Breast milk jaundice; type of feeding</td><td>1</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false},{"number":28,"title":"","stemText":"An 8 day old neonate has been brought to the emergency department by concerned parents. In the last 2 days she been drowsy, had poor feeding and then today had a pale floppy episode after a small mucous vomit. She is now pale but crying and moving. She was born at term without complications and her parents report that her older 2 siblings have a mild viral illness. Her initial obs are as follows\n\nHR 140,\n\nBP 102/90\n\nSats 100%\n\nRR 80\n\nBGL 7.5","parts":[{"id":"a","label":"Part A","prompt":"What are the 3 most likely diagnoses in this neonate? (3 marks)"},{"id":"b","label":"Part B","prompt":"What initial investigations or bedside tests would you order to confirm the diagnosis and why? (5 marks)"},{"id":"c","label":"Part C","prompt":"Outline your key management steps for this condition. (4 marks)"}],"propPages":[],"questionPages":[],"answerPages":[],"modelAnswerHtml":"<div class=\"extracted-answer\"><section class=\"answer-part\"><h5>Part A</h5><div class=\"answer-line\"><strong>Sepsis, Congenital Cardiac, </strong>BRUE, surgical (NEC, hernia, volvulous), metabolic (CAH,</div><div class=\"answer-line\">inborn error), NAI (head injury)</div><div class=\"answer-line\">Marking -must have Bold plus one</div></section><section class=\"answer-part\"><h5>Part B</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\">includes BSL, give initial electrolytes, is there</td></tr><tr><td colspan=\"2\">ischemia or a metabolic acidosis driving</td></tr><tr><td colspan=\"2\">tachypnoea,</td></tr><tr><td><strong>Cultures – blood and </strong></td><td>? infection source</td></tr><tr><td colspan=\"2\"><strong>urine </strong></td></tr><tr><td><strong>CXR/AXR</strong></td><td>Pneumonia,? large cardiac shadow or failure,</td></tr><tr><td colspan=\"2\">dilated bowel loops</td></tr><tr><td><strong>Pre and post ductal sats</strong></td><td>Duct dependent lesion</td></tr><tr><td><strong>LP</strong></td><td>? infection source, meningitis</td></tr><tr><td><strong>Bloods</strong></td><td>Liver and bilirubin</td></tr><tr><td colspan=\"2\">Test+ reasoning = 1 mark</td></tr><tr><td colspan=\"2\">She deteriorates and becomes mottled and floppy.  On repeat exam she is still tachypnoeic</td></tr><tr><td colspan=\"2\">and no longer has palpable femoral pulses.  She has developing bilateral crepitations</td></tr><tr><td colspan=\"2\">Observations:</td></tr><tr><td colspan=\"2\">HR 150</td></tr><tr><td colspan=\"2\">BP 85/62.</td></tr><tr><td colspan=\"2\">Saturations R Arm 98% and L Leg 57%</td></tr><tr><td colspan=\"2\">RR &gt;80</td></tr></tbody></table></div></section><section class=\"answer-part\"><h5>Part C</h5><div class=\"extracted-answer-table-wrap\"><table class=\"extracted-answer-table\"><tbody><tr><td colspan=\"2\"><strong>Antibiotics </strong>– Benzylpenicillin, Cefuroxime +/- acyclovir plus dose</td></tr><tr><td>-</td><td>Intubation/ airway support</td></tr><tr><td>-</td><td>Transfer to tertiary paediatric unit</td></tr><tr><td>-</td><td>Fluids must be very cautious</td></tr></tbody></table></div></section></div>","answerExtractionVerified":true,"answerSourceRetained":false}]);
